      //   error out <- Step.Result.Error
      await callRFmxSpecAnSelectMeasurementSingle(); // Select Single DPD Measurement [Action]
      //   Selector String <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
      //   RFmx Instrument Handle In <- FileGlobals.Device_Handles.RFmx
      //   RFSG Instrument Handle In <- FileGlobals.Device_Handles.RFSG
      //   Reference Waveform <- FileGlobals.Current_Sweep_Step.Loaded_Waveform
      //   Memory Polynomial Configuration <- FileGlobals.Configurations.Analyzer.SpecAn_DPD.DPD_Memory_Polynomial_Configuration
      //   RFmx Instrument Handle Out <- FileGlobals.Device_Handles.RFmx
      //   RFSG Instrument Handle Out <- FileGlobals.Device_Handles.RFSG
      //   error out <- Step.Result.Error
      await callPerformMemoryPolynomial(); // DPD Perform Memory Polynomial [Action]
    }
    for (final element in ts.iterate(measurementNames)) {
      currentMeasurement = element as String;
      // Select the appropriate action based on which measurement is selected
      {
        final select1 = currentMeasurement;
        var matched1 = false;
        // AMPM Method
        if (!matched1 && select1 == 'AMPM') {
          matched1 = true;
          //   Result Name <- ""
          //   Selector String <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
          //   Instrument Handle In <- FileGlobals.Device_Handles.RFmx
          //   Auto Level Configuration <- FileGlobals.Configurations.Analyzer.Auto_Level_Configuration
          //   Auto Level Bandwidth (Hz) <- 400000000
          //   Enable All Traces (F) <- False
          //   error out <- Step.Result.Error
          await callSpecAnSelectAndInitiateMeasurements(); // Select and Initiate SpecAn AMPM Measurement [Action]
          //   Selector String <- FileGlobals.Configurations.Analyzer.RFmxSpecAn_Selector_String
          //   RFmx Handle In <- FileGlobals.Device_Handles.RFmx
          //   AMPM Results <- FileGlobals.Current_Sweep_Step.Results.SpecAn_AMPM_Results
          //   error out <- Step.Result.Error
          await callSpecAnFetchAmpm(); // SpecAn Fetch AMPM [Action]
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.AMPM_Mean_LinerGain_dB =
              currentSweepStep.Results.SpecAn_AMPM_Results.Mean_Linear_Gain__dB_; // Map Results
          currentSweepStep.Input_and_Output.MEAS.AMPM_Mean_RMS_EVM =
              currentSweepStep.Results.SpecAn_AMPM_Results.Mean_RMS_EVM____; // Map Results (cont.)
        }
        // Adjacent Channel Power Measurement
        if (!matched1 && select1 == 'ACP') {
          matched1 = true;
          //   Result Name <- ""
          //   Selector String <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          //   Instrument Handle In <- FileGlobals.Device_Handles.RFmx
          //   Auto Level Configuration <- FileGlobals.Configurations.Analyzer.Auto_Level_Configuration
          //   Enable All Traces (F) <- False
          //   error out <- Step.Result.Error
          await callNrSelectAndInitiateMeasurements(); // Select and Initiate NR ACP Measurement [Action]
          //   Selector String <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          //   RFmx Handle In <- FileGlobals.Device_Handles.RFmx
          //   ACP Results <- FileGlobals.Current_Sweep_Step.Results.NR_ACP_Results
          //   error out <- Step.Result.Error
          await callNrFetchAcp(); // NR Fetch ACP [Action]
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.ACP_CC0_Absolute_Power_dBm =
              currentSweepStep.Results.NR_ACP_Results.Component_Carrier_Results[0].Absolute_Power__dBm_; // Map Results
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Upper_Absolute_Power_dBm = currentSweepStep
              .Results
              .NR_ACP_Results
              .Offset_Results[0]
              .Upper_Absolute_Power__dBm_; // Map Results (cont.)
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Upper_Relative_Power_dB = currentSweepStep
              .Results
              .NR_ACP_Results
              .Offset_Results[0]
              .Upper_Relative_Power__dB_; // Map Results (cont.)
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Lower_Absolute_Power_dBm = currentSweepStep
              .Results
              .NR_ACP_Results
              .Offset_Results[0]
              .Lower_Absolute_Power__dBm_; // Map Results (cont.)
          currentSweepStep.Input_and_Output.MEAS.ACP_Offset0_Lower_Relative_Power_dB = currentSweepStep
              .Results
              .NR_ACP_Results
              .Offset_Results[0]
              .Lower_Relative_Power__dB_; // Map Results (cont.)
        }
        // EVM Measurement
        if (!matched1 && select1 == 'EVM') {
          matched1 = true;
          //   Result Name <- ""
          //   Selector String <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          //   Instrument Handle In <- FileGlobals.Device_Handles.RFmx
          //   Auto Level Configuration <- FileGlobals.Configurations.Analyzer.Auto_Level_Configuration
          //   Enable All Traces (F) <- False
          //   error out <- Step.Result.Error
          await callNrSelectAndInitiateMeasurements(); // Select and Initiate NR ModAcc Measurement [Action]
          //   Selector String <- FileGlobals.Configurations.Analyzer.RFmx_Selector_String
          //   RFmx Handle In <- FileGlobals.Device_Handles.RFmx
          //   ModAcc Results <- FileGlobals.Current_Sweep_Step.Results.NR_ModAcc_Results
          //   error out <- Step.Result.Error
          await callNrFetchModAcc(); // NR Fetch ModAcc [Action]
          // Take the results that are dumped in full to the Results container and map them to specific spreadsheet output variables
          currentSweepStep.Input_and_Output.MEAS.RMS_Composite_EVM_Percent = currentSweepStep
              .Results
              .NR_ModAcc_Results
              .Component_Carrier_Results[0]
              .Mean_RMS_Composite_EVM; // Map Results
        }
      }
    }
  } finally {
    // ── cleanup ──
    //   RFSG handle <- FileGlobals.Device_Handles.RFSG
    //   Timeout (ms) <- 1000
    //   error out <- Step.Result.Error
    await callAbortGeneration(); // Abort Dynamic Generation [Action]
  }

  return run.status;
}

/// Sequence `SequenceFileLoad`.
Future<String> sequenceFileLoad() async {
  final run = ts.SequenceRun();
  final dynamic firstLaunchMessageResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ButtonHit': 0,
    'Response': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of First Launch Message

  // popup title: NameOf(Step)
  // popup message: @"If this is your first time opening this example sequence, please make sure to check the following: | - To use the proper RF devices, in the Variable pane navigate to FileGlobals.Static_Station_Configs.Device_Names  |   and enter the device identifiers there.  | - When using a PXIe 5830/31 enter the respective portnames in FileGlobals.Configurations.Analyzer.Common_Config.SelectedPorts and in |   FileGlobals.Configurations.Generator.RFSGConfig.SelectedPorts. | - You can change the waveform configuration under FileGlobals.Static_Station_Configs.Waveform_Configs.  | - All other Analyzer and Generator configurations can be found in the Configurations Container. | - The sequence will write a CSV result file in <./DataFiles/Results/>. You can change the parameters and measurements written to the file in  |   FileGlobals.Current_Sweep_Step.Input_and_Output and by adapting the 'Map Results' expression step in the Measure subsequence. | Feel free to keep this message from appearing next time you load the sequence by removing the 'SequenceFileLoad' callback from the Sequences pane."
  // popup buttons: "OK"
  // First Launch Message [MessagePopup]: acts through ts.stepHost
  final popup = await ts.stepHost.messagePopup(
    title: 'First Launch Message',
    message:
        'If this is your first time opening this example sequence, please make sure to check the following:\n\n- To use the proper RF devices, in the Variable pane navigate to FileGlobals.Static_Station_Configs.Device_Names \n  and enter the device identifiers there. \n\n- When using a PXIe 5830/31 enter the respective portnames in FileGlobals.Configurations.Analyzer.Common_Config.SelectedPorts and in\n  FileGlobals.Configurations.Generator.RFSGConfig.SelectedPorts.\n\n- You can change the waveform configuration under FileGlobals.Static_Station_Configs.Waveform_Configs. \n\n- All other Analyzer and Generator configurations can be found in the Configurations Container.\n\n- The sequence will write a CSV result file in <./DataFiles/Results/>. You can change the parameters and measurements written to the file in \n  FileGlobals.Current_Sweep_Step.Input_and_Output and by adapting the \'Map Results\' expression step in the Measure subsequence.\n\nFeel free to keep this message from appearing next time you load the sequence by removing the \'SequenceFileLoad\' callback from the Sequences pane.',
    buttons: ['OK', '', '', '', '', ''],
  );
  firstLaunchMessageResult.ButtonHit = popup.buttonHit;
  firstLaunchMessageResult.Response = popup.response;
  firstLaunchMessageResult.Status = 'Done';
  run.record(firstLaunchMessageResult.Status);

  return run.status;
}

